using System.Collections.Concurrent;
using System.Diagnostics;
using System.Text;
using System.Text.Json;
using OrderProcessingSystem.Shared.Exceptions;
using OrderProcessingSystem.Shared.Logging;
using OrderProcessingSystem.Shared.Models;
using OrderProcessingSystem.Shared.Repositories;
using OrderProcessingSystem.Shared.Storage;

namespace OrderProcessingSystem.Phase2;

public sealed class PricingService
{
    private readonly JsonFileStore _store; private readonly CustomerRepository _customers; private readonly CouponRepository _coupons; private readonly HashSet<int> _failShipping;
    public PricingService(JsonFileStore store,CustomerRepository customers,CouponRepository coupons,IEnumerable<int>? failShippingForOrderIds=null){_store=store;_customers=customers;_coupons=coupons;_failShipping=(failShippingForOrderIds??Array.Empty<int>()).ToHashSet();}
    public async Task<decimal> CalculateSubTotalAsync(Order order,CancellationToken ct){await Latency.QueryAsync("PricingService",$"Executing product price query for Order #{order.Id}...",ct);var all=await _store.ReadAsync<Product>(DataFiles.Products,ct);var map=all.ToDictionary(p=>p.Id);decimal subtotal=0;foreach(var i in order.Items){if(!map.TryGetValue(i.ProductId,out var p))throw new InvalidOperationException($"Product #{i.ProductId} not found during pricing");i.UnitPrice=p.Price;subtotal+=p.Price*i.Quantity;}order.SubTotal=Round(subtotal);return order.SubTotal;}
    public async Task<decimal> GetDiscountAsync(Order order,CancellationToken ct){await Latency.StepAsync("Discount API","DNS/handshake...",150,ct);await Latency.StepAsync("Discount API",$"Sending discount request for Order #{order.Id}...",300,ct);await Latency.StepAsync("Discount API","Waiting for response...",Random.Shared.Next(500,1501),ct);var c=await _customers.GetByIdAsync(order.CustomerId,ct)??throw new InvalidOperationException($"Customer #{order.CustomerId} not found during discount calculation");int pct=c.LoyaltyTier switch{LoyaltyTier.Bronze=>0,LoyaltyTier.Silver=>5,LoyaltyTier.Gold=>10,_=>0};if(order.CouponCode is not null){var cp=await _coupons.GetByCodeAsync(order.CouponCode,ct);if(cp is null)throw new InvalidCouponException($"Coupon '{order.CouponCode}' does not exist");if(cp.ExpiryDate.Date<DateTime.Today)throw new InvalidCouponException($"Coupon '{order.CouponCode}' has expired");pct+=cp.DiscountPercent;}pct=Math.Min(30,pct);return Round(order.SubTotal*pct/100m);}
    public async Task<decimal> CalculateShippingCostAsync(Order order,CancellationToken ct){await Latency.StepAsync("Shipping API","DNS/handshake...",150,ct);if(_failShipping.Contains(order.Id))throw new ShippingProviderUnavailableException("Shipping provider unavailable");await Latency.StepAsync("Shipping API",$"Sending shipping quote for Order #{order.Id}...",300,ct);await Latency.StepAsync("Shipping API","Waiting for response...",Random.Shared.Next(500,1501),ct);var products=await _store.ReadAsync<Product>(DataFiles.Products,ct);var p=products.ToDictionary(x=>x.Id);decimal weight=order.Items.Sum(i=>p[i.ProductId].WeightKg*i.Quantity);int qty=order.Items.Sum(i=>i.Quantity);return order.SubTotal>=1000m?0m:Round(5m+1.50m*qty+2m*weight);}
    public async Task PriceOrderAsync(Order order,CancellationToken ct){await CalculateSubTotalAsync(order,ct);var discountTask=GetDiscountAsync(order,ct);var shippingTask=CalculateShippingCostAsync(order,ct);await Task.WhenAll(discountTask,shippingTask);order.Discount=await discountTask;order.ShippingCost=await shippingTask;order.TotalAmount=Round(order.SubTotal-order.Discount+order.ShippingCost);}
    public async Task PriceOrderSequentialAsync(Order order,CancellationToken ct){await CalculateSubTotalAsync(order,ct);order.Discount=await GetDiscountAsync(order,ct);order.ShippingCost=await CalculateShippingCostAsync(order,ct);order.TotalAmount=Round(order.SubTotal-order.Discount+order.ShippingCost);}
    public static decimal Round(decimal x)=>Math.Round(x,2,MidpointRounding.AwayFromZero);
}
public sealed class InvoiceGenerator
{
    private readonly JsonFileStore _store;public InvoiceGenerator(JsonFileStore s)=>_store=s;
    public async Task GenerateAsync(Order order,CancellationToken ct){long render=await Task.Run(()=>{long h=order.Id;for(int i=0;i<20_000_000;i++){if((i&0x3FFF)==0)ct.ThrowIfCancellationRequested();h=(h*31+i)%1_000_000_007;}return h;},ct);ct.ThrowIfCancellationRequested();var path=Path.Combine(_store.DataDirectory,DataFiles.InvoicesDirectory,$"invoice_{order.Id}.txt");var text=$"Invoice #{order.Id}\nCustomer ID: {order.CustomerId}\nSubtotal: {order.SubTotal:F2}\nDiscount: {order.Discount:F2}\nShipping: {order.ShippingCost:F2}\nTotal: {order.TotalAmount:F2}\nRender checksum: {render}\n";await File.WriteAllTextAsync(path,text,new UTF8Encoding(false),ct);}
}
public sealed class ReportGenerator
{
    private readonly JsonFileStore _store;private readonly OrderRepository _orders;private readonly ProductRepository _products;
    public ReportGenerator(JsonFileStore s,OrderRepository o,ProductRepository p){_store=s;_orders=o;_products=p;}
    public async Task<Report> GenerateAsync(CancellationToken ct){var ot=_orders.GetAllAsync(ct);var pt=_products.GetAllAsync(ct);await Task.WhenAll(ot,pt);var orders=await ot;var completed=orders.Where(x=>x.Status==OrderStatus.Completed).ToList();var products=(await pt).ToDictionary(x=>x.Id);var selling=completed.SelectMany(o=>o.Items.Select(i=>(i.ProductId,i.Quantity))).GroupBy(x=>x.ProductId).Select(g=>new{Id=g.Key,Qty=g.Sum(x=>x.Quantity)}).OrderByDescending(x=>x.Qty).ThenBy(x=>x.Id).FirstOrDefault();var revenue=completed.Sum(x=>x.TotalAmount);var r=new Report{TotalOrders=orders.Count,TotalRevenue=revenue,CompletedCount=completed.Count,RejectedCount=orders.Count(x=>x.Status==OrderStatus.Rejected),FailedCount=orders.Count(x=>x.Status==OrderStatus.Failed),PaymentFailedCount=orders.Count(x=>x.Status==OrderStatus.PaymentFailed),TopSellingProduct=selling is null?"None":products[selling.Id].Name,TopSellingQuantity=selling?.Qty??0,AverageOrderValue=completed.Count==0?0:PricingService.Round(revenue/completed.Count),GeneratedAt=DateTime.Now};var file=Path.Combine(_store.DataDirectory,DataFiles.ReportsDirectory,$"report_{DateTime.Now:yyyyMMdd_HHmmss}.json");var temp=file+"."+Guid.NewGuid().ToString("N")+".tmp";try{await File.WriteAllTextAsync(temp,JsonSerializer.Serialize(r,JsonFileStore.JsonOptions),new UTF8Encoding(false),ct);ct.ThrowIfCancellationRequested();File.Move(temp,file,true);}finally{if(File.Exists(temp))File.Delete(temp);}return r;}
}
public sealed class OrderProcessorV2
{
    private readonly ProductRepository _products;private readonly OrderRepository _orders;private readonly PricingService _pricing;private readonly InvoiceGenerator _invoices;private readonly ConcurrentDictionary<int,List<OrderItem>> _reserved=new();
    public OrderProcessorV2(ProductRepository p,OrderRepository o,PricingService pricing,InvoiceGenerator i){_products=p;_orders=o;_pricing=pricing;_invoices=i;}
    public IReadOnlyList<OrderItem> GetReservedItems(int orderId)=>_reserved.TryGetValue(orderId,out var rows)?rows.ToList():Array.Empty<OrderItem>();
    public async Task<bool> ProcessValidatedOrderAsync(Order order,CancellationToken ct){var reserved=new List<OrderItem>();_reserved[order.Id]=reserved;foreach(var item in order.Items){if(!await _products.ReserveStockAsync(item.ProductId,item.Quantity,ct)){foreach(var r in reserved)await _products.ReleaseStockAsync(r.ProductId,r.Quantity,CancellationToken.None);_reserved.TryRemove(order.Id,out _);var p=await _products.GetByIdAsync(item.ProductId,CancellationToken.None);order.Status=OrderStatus.Rejected;order.FailureReason=$"Insufficient stock for '{p?.Name??$"Product #{item.ProductId}"}'";await _orders.SaveAsync(order,ct);return false;}reserved.Add(new OrderItem{ProductId=item.ProductId,Quantity=item.Quantity,UnitPrice=item.UnitPrice});}await _pricing.PriceOrderAsync(order,ct);await _invoices.GenerateAsync(order,ct);order.Status=OrderStatus.Completed;order.FailureReason=null;await _orders.SaveAsync(order,ct);_reserved.TryRemove(order.Id,out _);return true;}
}
public sealed class RaceConditionDemo
{
    private readonly JsonFileStore _store;private readonly ProductRepository _products;public RaceConditionDemo(JsonFileStore s,ProductRepository p){_store=s;_products=p;}
    public async Task RunAsync(CancellationToken ct){Console.WriteLine("===== Race condition demo: unsafe reservation =====");await _products.SetStockAsync(4,1,ct);var unsafeResults=await Task.WhenAll(_products.ReserveStockUnsafeAsync(4,1,ct),_products.ReserveStockUnsafeAsync(4,1,ct));var p=await _products.GetByIdAsync(4,ct);Console.WriteLine($"Unsafe results: {string.Join(", ",unsafeResults)}; stock read from file: {p?.StockQuantity}. Both stale reads succeed and overwrite each other.");Console.WriteLine("===== Race condition demo: safe reservation =====");await _products.SetStockAsync(4,1,ct);var safe=await Task.WhenAll(_products.ReserveStockAsync(4,1,ct),_products.ReserveStockAsync(4,1,ct));p=await _products.GetByIdAsync(4,ct);Console.WriteLine($"Safe results: {string.Join(", ",safe)}; stock read from file: {p?.StockQuantity}.");}
}
public sealed class Phase2Runner
{
    private readonly JsonFileStore _store;private readonly DataSeeder _seeder;public Phase2Runner(JsonFileStore s,DataSeeder d){_store=s;_seeder=d;}
    public async Task RunAsync(CancellationToken ct)
    {
        await _seeder.ResetAsync(ct);await new RaceConditionDemo(_store,new ProductRepository(_store)).RunAsync(ct);await _seeder.ResetAsync(ct);
        var customerRepo=new CustomerRepository(_store);var productRepo=new ProductRepository(_store);var couponRepo=new CouponRepository(_store);var ordersRepo=new OrderRepository(_store);var incoming=await new IncomingOrderRepository(_store).GetAllAsync(ct);
        var p1=Clone(incoming.Single(x=>x.Id==1));var sequentialPricing=new PricingService(_store,customerRepo,couponRepo,Array.Empty<int>());var concurrentPricing=new PricingService(_store,customerRepo,couponRepo,Array.Empty<int>());Log.ResetThreadTracking();int seqPoolBefore=ThreadPool.ThreadCount;var watch=Stopwatch.StartNew();await sequentialPricing.PriceOrderSequentialAsync(p1,ct);watch.Stop();var seq=watch.Elapsed;int seqThreads=Log.DistinctThreads;int seqPoolAfter=ThreadPool.ThreadCount;var p2=Clone(incoming.Single(x=>x.Id==1));Log.ResetThreadTracking();int concurrentPoolBefore=ThreadPool.ThreadCount;watch.Restart();await concurrentPricing.PriceOrderAsync(p2,ct);watch.Stop();int concurrentThreads=Log.DistinctThreads;int concurrentPoolAfter=ThreadPool.ThreadCount;Console.WriteLine($"Pricing Order #1 sequential: {seq.TotalSeconds:F2}s; distinct threads={seqThreads}; ThreadPool.ThreadCount {seqPoolBefore}->{seqPoolAfter}");Console.WriteLine($"Pricing Order #1 concurrent: {watch.Elapsed.TotalSeconds:F2}s; distinct threads={concurrentThreads}; ThreadPool.ThreadCount {concurrentPoolBefore}->{concurrentPoolAfter}");Console.WriteLine($"Order #1: {p2.SubTotal:F2} / {p2.Discount:F2} / {p2.ShippingCost:F2} / {p2.TotalAmount:F2}");
        var validator=new OrderProcessingSystem.Phase1.OrderValidator(customerRepo,productRepo,couponRepo);var validateTasks=incoming.Select(async o=>{try{await validator.ValidateOrderAsync(o,ct);await ordersRepo.SaveAsync(o,ct);}catch(OperationCanceledException) when(ct.IsCancellationRequested){o.Status=OrderStatus.Pending;o.FailureReason="Cancelled";try{await ordersRepo.SaveCompensationAsync(o,CancellationToken.None);}catch(Exception ex){Log.Error($"Could not save cancellation state for Order #{o.Id}: {ex.Message}");}}}).ToArray();await Task.WhenAll(validateTasks);if(ct.IsCancellationRequested){foreach(var pendingOrder in incoming.Where(o=>o.Status==OrderStatus.Validated)){pendingOrder.Status=OrderStatus.Pending;pendingOrder.FailureReason="Cancelled";try{await ordersRepo.SaveCompensationAsync(pendingOrder,CancellationToken.None);}catch(Exception ex){Log.Error($"Could not save cancellation state for Order #{pendingOrder.Id}: {ex.Message}");}}throw new OperationCanceledException(ct);}var validated=await ordersRepo.GetByStatusAsync(OrderStatus.Validated,ct);
        ct.ThrowIfCancellationRequested();
        BlockingWaitDemo.Run(ct);
        var pricier=new PricingService(_store,customerRepo,couponRepo,new[]{7});var inv=new InvoiceGenerator(_store);var proc=new OrderProcessorV2(productRepo,ordersRepo,pricier,inv);Log.ResetThreadTracking();int processingPoolBefore=ThreadPool.ThreadCount;watch.Restart();var work=validated.Select(o=>proc.ProcessValidatedOrderAsync(o,ct)).ToList();Console.WriteLine($"Task[0] immediate status: {work[0].Status}");try{await Task.Delay(1000,ct);}catch(OperationCanceledException) when(ct.IsCancellationRequested){Log.Warning("Cancellation requested while observing concurrent task states; collecting every task for compensation.");}for(int i=0;i<work.Count;i++)Console.WriteLine($"Order #{validated[i].Id} task status after observation window: {work[i].Status}");
        for(int i=0;i<work.Count;i++){try{await work[i];}catch(OperationCanceledException) when(ct.IsCancellationRequested){await HandleCancelledAsync(validated[i],CancellationToken.None);}catch(Exception ex){var o=validated[i];await SafeReleaseAsync(o,CancellationToken.None);if(ct.IsCancellationRequested){o.Status=OrderStatus.Pending;o.FailureReason="Cancelled";try{await ordersRepo.SaveCompensationAsync(o,CancellationToken.None);}catch{}Console.WriteLine($"Task for Order #{o.Id}: {work[i].Status}; marked Cancelled.");}else{o.Status=OrderStatus.Failed;o.FailureReason=ex.Message;try{await ordersRepo.SaveCompensationAsync(o,CancellationToken.None);}catch(Exception save){Log.Error($"Could not save failed Order #{o.Id}: {save.Message}");}Console.WriteLine($"Task for Order #{o.Id}: {work[i].Status}; marked Failed: {ex.Message}");}}}
        watch.Stop();int processingThreads=Log.DistinctThreads;int processingPoolAfter=ThreadPool.ThreadCount;for(int i=0;i<work.Count;i++)Console.WriteLine($"Order #{validated[i].Id} final task status: {work[i].Status}");var all=await ordersRepo.GetAllAsync(CancellationToken.None);Console.WriteLine($"Phase 2 concurrent processing: {watch.Elapsed.TotalSeconds:F2}s; distinct logged threads={processingThreads}; ThreadPool.ThreadCount {processingPoolBefore}->{processingPoolAfter}; orders.json count={all.Count}; completed={all.Count(x=>x.Status==OrderStatus.Completed)}, rejected={all.Count(x=>x.Status==OrderStatus.Rejected)}, failed={all.Count(x=>x.Status==OrderStatus.Failed)}");if(ct.IsCancellationRequested){int cancelledCount=all.Count(x=>x.Status==OrderStatus.Pending&&x.FailureReason=="Cancelled");Console.WriteLine($"Run cancelled — {all.Count-cancelledCount} orders finished, {cancelledCount} cancelled");}
        if(!ct.IsCancellationRequested){var reportWatch=Stopwatch.StartNew();var reportTask=new ReportGenerator(_store,ordersRepo,productRepo).GenerateAsync(ct);Console.WriteLine("Generating report...");var report=await reportTask;reportWatch.Stop();Console.WriteLine($"Report generated in {reportWatch.Elapsed.TotalSeconds:F2}s: "+JsonSerializer.Serialize(report,JsonFileStore.JsonOptions));}
        async Task SafeReleaseAsync(Order o,CancellationToken cleanupCt){var reserved=proc.GetReservedItems(o.Id);if(reserved.Count==0)return;try{await productRepo.ReleaseItemsAsync(reserved,cleanupCt);}catch(Exception e){Log.Error($"Stock release for Order #{o.Id} failed: {e.Message}");}}
        async Task HandleCancelledAsync(Order o,CancellationToken cleanupCt){await SafeReleaseAsync(o,cleanupCt);o.Status=OrderStatus.Pending;o.FailureReason="Cancelled";try{await ordersRepo.SaveCompensationAsync(o,cleanupCt);}catch{} }
    }
    private static Order Clone(Order o)=>new(){Id=o.Id,CustomerId=o.CustomerId,Items=o.Items.Select(i=>new OrderItem{ProductId=i.ProductId,Quantity=i.Quantity,UnitPrice=i.UnitPrice}).ToList(),CouponCode=o.CouponCode,Status=o.Status,CreatedAt=o.CreatedAt};
}
